  let started = false; // whether any input has arrived; a BOM is only stripped from the first character
  let finished = false;
  let afterCR = false; // the previous character was a CR, so an LF now completes a CRLF
  // Position of the next character.
  let line = 1;
  let column = 1;
  let recordLine = 1;
  let fieldLine = 1;
  let fieldColumn = 1;
  // Pieces of the current field that were cut off by a chunk boundary or an escaped quote.
  const parts = [];
  let record = [];
  let names = null; // column names, once the header record has been read
  let seenNames = header ? new Set() : null; // set while the header record is being read
  let completed = [];

  function takeField() {
    const value = parts.length === 1 ? parts[0] : parts.join('');
    parts.length = 0;
    return value;
  }

  function pushPart(chunk, from, to) {
    if (to > from) parts.push(chunk.slice(from, to));
  }

  function endField(value) {
    if (seenNames !== null) {
      if (seenNames.has(value)) {
        throw new CsvError(`Duplicate column name ${JSON.stringify(value)}`, fieldLine, fieldColumn);
      }
      seenNames.add(value);
    }
    record.push(value);
  }

  function endRecord() {
    const fields = record;
    record = [];
    state = RECORD_START;
    if (!header) {
      completed.push(fields);
    } else if (names === null) {
      names = fields;
      seenNames = null;
    } else if (fields.length !== names.length) {
      throw new CsvError(`Expected ${names.length} fields but found ${fields.length}`, recordLine, 1);
    } else {
      completed.push(toObject(names, fields));
    }
  }

  function consume(chunk) {
    let i = 0;
    if (!started && chunk.length > 0) {
      started = true;
      if (chunk.charCodeAt(0) === BOM) i = 1;
    }
    // Start, in this chunk, of the current field's text not yet copied into `parts`.
    let runStart = i;

    for (; i < chunk.length; i++) {
      const c = chunk.charCodeAt(i);
      const crlf = afterCR && c === LF;
      afterCR = c === CR;

      switch (state) {
        case RECORD_START:
          if (crlf || (skipEmptyLines && (c === CR || c === LF))) break;
          recordLine = line;
        // falls through
        case FIELD_START:
          fieldLine = line;
          fieldColumn = column;
          if (c === QUOTE) {
            state = QUOTED;
            runStart = i + 1;
          } else if (c === delimiter) {
            endField('');
            state = FIELD_START;
          } else if (c === CR || c === LF) {
            endField('');
            endRecord();
          } else {
            state = UNQUOTED;
            runStart = i;
          }
          break;
        case UNQUOTED:
          if (c === delimiter || c === CR || c === LF) {
            pushPart(chunk, runStart, i);
            endField(takeField());
            if (c === delimiter) state = FIELD_START;
            else endRecord();
          }
          break;
        case QUOTED:
          if (c === QUOTE) {
            pushPart(chunk, runStart, i);
            state = QUOTE_IN_QUOTED;
          }
          break;
        case QUOTE_IN_QUOTED:
          if (c === QUOTE) {
            // The second quote of `""` is the literal one, so the next run starts at it.
            state = QUOTED;
            runStart = i;
          } else if (c === delimiter || c === CR || c === LF) {
            endField(takeField());
            if (c === delimiter) state = FIELD_START;
            else endRecord();
          } else {
            throw new CsvError(
              `Unexpected ${JSON.stringify(chunk[i])} after the closing quote of a field; expected a delimiter or line break`,
              line,
              column,
            );
          }
          break;
      }

      if (c === CR || (c === LF && !crlf)) {
        line++;
        column = 1;
      } else if (c !== LF) {
        column++;
      }
    }

    if (state === UNQUOTED || state === QUOTED) pushPart(chunk, runStart, chunk.length);
  }

  function finish() {
    if (state === QUOTED) throw new CsvError('Quoted field is never closed', fieldLine, fieldColumn);
    if (state !== RECORD_START) {
      endField(takeField());
      endRecord();
    }
  }

  function run(step) {
    if (finished) throw new Error('The CSV parser has already ended or failed; create a new parser');
    try {
      step();
    } catch (err) {
      finished = true;
      throw err;
    }
    const records = completed;
    completed = [];
    return records;
  }

  return {
    write(chunk) {
      return run(() => {
        if (typeof chunk !== 'string') throw new TypeError(`chunk must be a string, got ${describe(chunk)}`);
        consume(chunk);
      });
    },
    end() {
      return run(() => {
        finish();
        finished = true;
      });
    },
  };
}

/** Parses a whole CSV string. Throws `CsvError` for malformed input; see `createParser`. */
function parse(text, options = {}) {
  if (typeof text !== 'string') throw new TypeError(`text must be a string, got ${describe(text)}`);
  const parser = createParser(options);
  const records = parser.write(text);
  for (const record of parser.end()) records.push(record);
  return records;
}

function formatValue(value, rowIndex, fieldIndex) {
  if (typeof value === 'string') return value;
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  if (value === null || value === undefined) return '';
  throw new TypeError(`Cannot write a value of type ${describe(value)} (row ${rowIndex}, field ${fieldIndex})`);
}

function needsQuotes(field, delimiter) {
  return (
    field.includes(delimiter) ||
    field.includes('"') ||
    field.includes('\r') ||
    field.includes('\n') ||
    field.startsWith(' ') ||
    field.endsWith(' ')
  );
}

// `rowIndex` is -1 for the header row. `leading` marks the first record of the output, whose
// first field must be quoted if it starts with a BOM, or parse would strip that character.
function formatRecord(values, delimiter, rowIndex, leading) {
  const fields = values.map((value, i) => formatValue(value, rowIndex, i));
  if (fields.length === 1 && fields[0] === '') return '""';
  return fields
    .map((field, i) => {
      const quote = needsQuotes(field, delimiter) || (leading && i === 0 && field.charCodeAt(0) === BOM);
      return quote ? `"${field.replaceAll('"', '""')}"` : field;
    })
    .join(delimiter);
}

function readHeader(header) {
  if (header === undefined || header === false) return null;
  if (!Array.isArray(header) || !header.every((name) => typeof name === 'string')) {
    throw new TypeError('header must be an array of column names (strings)');
  }
  return header;
}

/**
 * Writes rows as CSV. Each row is an array of values, or, when `options.header` is an array of
 * column names, an object whose own properties are written in header order.
 */
function stringify(rows, options = {}) {
  if (!Array.isArray(rows)) throw new TypeError(`rows must be an array, got ${describe(rows)}`);
  checkOptions(options);
  const delimiter = readDelimiter(options.delimiter);
  const eol = options.eol === undefined ? '\r\n' : options.eol;
  if (!EOLS.includes(eol)) {
    throw new TypeError(`eol must be '\\r\\n' or '\\n', got ${JSON.stringify(eol) ?? describe(eol)}`);
  }
  const header = readHeader(options.header);
  if (rows.length === 0) return '';

  const lines = [];
  if (header !== null) lines.push(formatRecord(header, delimiter, -1, true));
  rows.forEach((row, rowIndex) => {
    let values;
    if (Array.isArray(row)) {
      values = row;
    } else if (header !== null && row !== null && typeof row === 'object') {
      values = header.map((name) => (Object.hasOwn(row, name) ? row[name] : undefined));
    } else {
      const expected = header === null ? 'an array' : 'an array or an object';
      throw new TypeError(`row ${rowIndex} must be ${expected}, got ${describe(row)}`);
    }
    lines.push(formatRecord(values, delimiter, rowIndex, lines.length === 0));
  });
  return lines.join(eol) + eol;
}

module.exports = { parse, createParser, stringify, CsvError };

