'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const csv = require('../src/csv.js');

const { parse, CsvError } = csv;

// Asserts that parsing `text` throws a CsvError at the given position.
function assertCsvError(text, options, line, column) {
  assert.throws(
    () => parse(text, options),
    (err) => {
      assert.ok(err instanceof CsvError, `expected CsvError, got ${err}`);
      assert.deepEqual({ line: err.line, column: err.column }, { line, column }, err.message);
      return true;
    },
  );
}

describe('module', () => {
  it('is loadable through package.json main', () => {
    assert.equal(require('..'), csv);
    assert.deepEqual(Object.keys(csv).sort(), ['CsvError', 'createParser', 'parse', 'stringify']);
  });
});

describe('parse', () => {
  it('returns [] for an empty string', () => {
    assert.deepEqual(parse(''), []);
  });

  it('throws TypeError when text is not a string', () => {
    for (const text of [undefined, null, 42, ['a'], { a: 1 }, Buffer.from('a,b')]) {
      assert.throws(() => parse(text), TypeError, String(text));
    }
  });

  it('splits fields on commas and records on line breaks', () => {
    assert.deepEqual(parse('a,b,c\n1,2,3'), [
      ['a', 'b', 'c'],
      ['1', '2', '3'],
    ]);
  });

  it('accepts CRLF, LF and CR mixed in one input', () => {
    assert.deepEqual(parse('a\r\nb\nc\rd'), [['a'], ['b'], ['c'], ['d']]);
  });

  it('keeps empty fields, including leading and trailing ones', () => {
    assert.deepEqual(parse(',a,,\n,'), [
      ['', 'a', '', ''],
      ['', ''],
    ]);
  });

  describe('line breaks at the end and empty lines', () => {
    const cases = [
      ['a\n', [['a']]],
      ['a\r\n', [['a']]],
      ['a\r', [['a']]],
      ['\n', [['']]],
      ['a\n\n', [['a'], ['']]],
      ['a\r\r\n', [['a'], ['']]],
      ['a\n\r', [['a'], ['']]],
      ['\r\n\r\n', [[''], ['']]],
      ['a\n\nb', [['a'], [''], ['b']]],
    ];
    for (const [text, expected] of cases) {
      it(`parses ${JSON.stringify(text)}`, () => {
        assert.deepEqual(parse(text), expected);
      });
    }
  });

  describe('skipEmptyLines', () => {
    it('skips empty lines of every line-break style', () => {
      assert.deepEqual(parse('\na\n\n\r\nb\r\r', { skipEmptyLines: true }), [['a'], ['b']]);
      assert.deepEqual(parse('\n\r\n\r', { skipEmptyLines: true }), []);
    });

    it('keeps lines holding an empty quoted field or whitespace', () => {
      assert.deepEqual(parse('""\n \n', { skipEmptyLines: true }), [[''], [' ']]);
    });
  });

  describe('byte order mark', () => {
    it('ignores a leading BOM', () => {
      assert.deepEqual(parse('\uFEFFa,b'), [['a', 'b']]);
      assert.deepEqual(parse('\uFEFF'), []);
      assert.deepEqual(parse('\uFEFF"a"'), [['a']]);
    });

    it('keeps a BOM that is not the first character', () => {
      assert.deepEqual(parse('a,\uFEFFb'), [['a', '\uFEFFb']]);
      assert.deepEqual(parse('\uFEFF\uFEFFa'), [['\uFEFFa']]);
    });

    it('does not count the ignored BOM as a column', () => {
      assertCsvError('\uFEFF"a"x', {}, 1, 4);
    });
  });

  describe('quoted fields', () => {
    it('treats delimiters and line breaks inside quotes as literal', () => {
      assert.deepEqual(parse('"a,b","c\nd","e\r\nf","g\rh"'), [['a,b', 'c\nd', 'e\r\nf', 'g\rh']]);
    });

    it('turns "" into one literal quote', () => {
      assert.deepEqual(parse('"say ""hi""",""""'), [['say "hi"', '"']]);
    });

    it('parses an empty quoted field', () => {
      assert.deepEqual(parse('"",""\n""'), [['', ''], ['']]);
    });

    it('treats a quote in an unquoted field as an ordinary character', () => {
      assert.deepEqual(parse('a"b,c""\n x"y"'), [
        ['a"b', 'c""'],
        [' x"y"'],
      ]);
    });

    it('ends a quoted field at the end of input', () => {
      assert.deepEqual(parse('a,"b"'), [['a', 'b']]);
    });
  });

  it('never trims whitespace', () => {
    assert.deepEqual(parse(' a , b\t,\t\n  '), [
      [' a ', ' b\t', '\t'],
      ['  '],
    ]);
  });

  it('keeps non-ASCII text intact', () => {
    assert.deepEqual(parse('café,"😀,👍"\n日本,ß'), [
      ['café', '😀,👍'],
      ['日本', 'ß'],
    ]);
  });

  describe('delimiter option', () => {
    it('splits on the given character', () => {
      assert.deepEqual(parse('a;b,c;"d;e"', { delimiter: ';' }), [['a', 'b,c', 'd;e']]);
      assert.deepEqual(parse('a\tb\n\tc', { delimiter: '\t' }), [
        ['a', 'b'],
        ['', 'c'],
      ]);
      assert.deepEqual(parse('a b', { delimiter: ' ' }), [['a', 'b']]);
    });

    it('throws TypeError for an invalid delimiter', () => {
      for (const delimiter of ['', ';;', '"', '\r', '\n', '\r\n', '\uD83D', '😀', 1, null, [',']]) {
        assert.throws(() => parse('a', { delimiter }), TypeError, JSON.stringify(delimiter));
      }
    });
  });

  it('throws TypeError for invalid options', () => {
    assert.throws(() => parse('a', null), TypeError);
    assert.throws(() => parse('a', 'header'), TypeError);
    assert.throws(() => parse('a', { header: 'yes' }), TypeError);
    assert.throws(() => parse('a', { skipEmptyLines: 1 }), TypeError);
  });
});

describe('parse with header', () => {
  it('turns records after the first into objects keyed by column name', () => {
    assert.deepEqual(parse('id,name\n1,Ann\n2,"B, b"\n', { header: true }), [
      { id: '1', name: 'Ann' },
      { id: '2', name: 'B, b' },
    ]);
  });

  it('returns [] when there is only a header', () => {
    assert.deepEqual(parse('a,b', { header: true }), []);
    assert.deepEqual(parse('a,b\r\n', { header: true }), []);
    assert.deepEqual(parse('', { header: true }), []);
  });

  it('strips a leading BOM from the first column name', () => {
    assert.deepEqual(parse('\uFEFFid\n7', { header: true }), [{ id: '7' }]);
  });

  it('treats an empty line as a one-field record', () => {
    assert.deepEqual(parse('only\n\nx', { header: true }), [{ only: '' }, { only: 'x' }]);
    assertCsvError('a,b\n\n1,2', { header: true }, 2, 1);
