'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { parse, createParser, CsvError } = require('../src/csv.js');

// Runs `fn` and returns either its result or a comparable description of what it threw.
function outcome(fn) {
  const records = [];
  try {
    fn(records);
    return { records };
  } catch (err) {
    if (!(err instanceof CsvError)) throw err;
    return { error: { message: err.message, line: err.line, column: err.column } };
  }
}

function parseInChunks(chunks, options) {
  return outcome((records) => {
    const parser = createParser(options);
    for (const chunk of chunks) records.push(...parser.write(chunk));
    records.push(...parser.end());
  });
}

// Deterministic PRNG so failures are reproducible.
function mulberry32(seed) {
  let a = seed;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function splitAt(text, cuts) {
  const chunks = [];
  let from = 0;
  for (const cut of cuts) {
    chunks.push(text.slice(from, cut));
    from = cut;
  }
  chunks.push(text.slice(from));
  return chunks;
}

describe('createParser', () => {
