it('stays linear in the input when a field and a record span many small chunks', () => {
  // A linear parser needs well under a second; one that rescans earlier input needs minutes.
  // The budget is checked inside the loops because node:test cannot time out a synchronous test.
  const budgetMs = 5000;
  const start = performance.now();
  const pieces = 200000;
  const parser = createParser();
  parser.write('"');
  for (let i = 0; i < pieces * 2; i++) {
    if (i === pieces) parser.write('",');
    const records = parser.write(i < pieces ? (i % 2 ? 'x' : '""') : 'y');
    assert.equal(records.length, 0);
    if (i % 1000 === 0 && performance.now() - start > budgetMs) {
      assert.fail(`${i} writes took over ${budgetMs} ms; time is not linear in the input`);
    }
  }
  const [record] = parser.write('\n');

