'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { parse, createParser, CsvError } = require('../src/csv.js');

// Runs `fn` and returns either its result or a comparable description of what it threw.
function outcome(fn) {
  const records = [];
  try {
    fn(records);
    return { records };
  } catch (err) {
    if (!(err instanceof CsvError)) throw err;
    return { error: { message: err.message, line: err.line, column: err.column } };
  }
}

function parseInChunks(chunks, options) {
  return outcome((records) => {
    const parser = createParser(options);
    for (const chunk of chunks) records.push(...parser.write(chunk));
    records.push(...parser.end());
  });
}

// Deterministic PRNG so failures are reproducible.
function mulberry32(seed) {
  let a = seed;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function splitAt(text, cuts) {
  const chunks = [];
  let from = 0;
  for (const cut of cuts) {
    chunks.push(text.slice(from, cut));
    from = cut;
  }
  chunks.push(text.slice(from));
  return chunks;
}

describe('createParser', () => {
  it('returns from each write only the records whose line break is in that chunk', () => {
    const parser = createParser();
    assert.deepEqual(parser.write('a,b\nc,'), [['a', 'b']]);
    assert.deepEqual(parser.write('d'), []);
    assert.deepEqual(parser.write('\ne\nf'), [['c', 'd'], ['e']]);
    assert.deepEqual(parser.end(), [['f']]);
  });

  it('returns a record ended by a CR at a chunk boundary and joins the LF that follows', () => {
    const parser = createParser();
    assert.deepEqual(parser.write('a\r'), [['a']]);
    assert.deepEqual(parser.write('\nb\r'), [['b']]);
    assert.deepEqual(parser.write('\r'), [['']]);
    assert.deepEqual(parser.write('\n'), []);
    assert.deepEqual(parser.end(), []);
  });

  it('holds a quoted field open across chunks until its closing quote is resolved', () => {
    const parser = createParser();
    assert.deepEqual(parser.write('"a\r'), []);
    assert.deepEqual(parser.write('\nb"'), []);
    assert.deepEqual(parser.write('"'), []);
    assert.deepEqual(parser.write('"\n'), [['a\r\nb"']]);
    assert.deepEqual(parser.end(), []);
  });

  it('returns [] from end() when nothing was written', () => {
    assert.deepEqual(createParser().end(), []);
  });

  it('returns objects in header mode and never returns the header', () => {
    const parser = createParser({ header: true });
    assert.deepEqual(parser.write('x,y\n'), []);
    assert.deepEqual(parser.write('1,2\n3,'), [{ x: '1', y: '2' }]);
    assert.deepEqual(parser.end(), [{ x: '3', y: '' }]);
  });

  it('strips a BOM only from the first character of the whole input', () => {
    const empty = createParser();
    empty.write('');
    empty.write('﻿a');
    assert.deepEqual(empty.end(), [['a']]);

    const later = createParser();
    later.write('a');
    later.write('﻿b');
    assert.deepEqual(later.end(), [['a﻿b']]);
  });

  it('validates options when created', () => {
    assert.throws(() => createParser({ delimiter: '"' }), TypeError);
    assert.throws(() => createParser({ header: 1 }), TypeError);
    assert.throws(() => createParser(null), TypeError);
  });

  it('throws TypeError for a chunk that is not a string', () => {
    for (const chunk of [undefined, null, 1, Buffer.from('a'), ['a']]) {
      assert.throws(() => createParser().write(chunk), TypeError);
    }
  });

  describe('after it is finished', () => {
    const finishers = {
      'end()': (parser) => assert.deepEqual(parser.end(), [{ a: 'x' }]),
      'a CsvError from write()': (parser) => assert.throws(() => parser.write('\n"y"z'), CsvError),
      'a CsvError from end()': (parser) => {
        parser.write('\n"y');
        assert.throws(() => parser.end(), CsvError);
      },
      'a TypeError from write()': (parser) => assert.throws(() => parser.write(5), TypeError),
    };
    for (const [name, finish] of Object.entries(finishers)) {
      it(`throws from both methods after ${name}`, () => {
        const parser = createParser({ header: true });
        parser.write('a\nx');
        finish(parser);
        assert.throws(() => parser.write('b'), /already ended or failed/);
        assert.throws(() => parser.end(), /already ended or failed/);
      });
    }
  });

  describe('matches parse() wherever the input is split', () => {
    const inputs = [
      ['a,b\r\nc,d\re,f\ng', {}],
      ['"a""b",c\r\n"d\r\ne"\r\n\r\n', {}],
      ['﻿"x"\r\n""\r\n\r\n', { skipEmptyLines: true }],
      ['"",""""\n" "', {}],
      ['h1;h2\r\n"1;1";2\r\n\r\n3;4\r', { delimiter: ';', header: true, skipEmptyLines: true }],
      ['a\n"b\r\n"x', {}],
      ['a\r\n"b""\r\nc', {}],
      ['a,b\r\n1,2,3\r\n"x"y', { header: true }],
      ['a,"b\r\nc",a,"b\r\nc"', { header: true }],
      ['😀,"é\r\n😀"', {}],
    ];

    for (const [text, options] of inputs) {
      it(JSON.stringify(text), () => {
        const expected = outcome((records) => records.push(...parse(text, options)));
        for (let cut = 0; cut <= text.length; cut++) {
          assert.deepEqual(parseInChunks(splitAt(text, [cut]), options), expected, `split at ${cut}`);
        }
        for (let a = 0; a <= text.length; a++) {
          for (let b = a; b <= text.length; b++) {
            assert.deepEqual(parseInChunks(splitAt(text, [a, b]), options), expected, `split at ${a}, ${b}`);
          }
        }
        assert.deepEqual(parseInChunks([...text.split(''), ''], options), expected, 'one code unit per chunk');
      });
    }

    it('on random CSV text split into random chunks', () => {
      const random = mulberry32(4180);
      const alphabet = ['a', 'b', ',', ',', '"', '"', '\r', '\n', '\r\n', ' ', '﻿'];
      for (let round = 0; round < 500; round++) {
        let text = '';
        const length = Math.floor(random() * 30);
        for (let i = 0; i < length; i++) text += alphabet[Math.floor(random() * alphabet.length)];
        const options = { header: random() < 0.3, skipEmptyLines: random() < 0.5 };
        const cuts = [];
        for (let i = 0; i <= text.length; i++) if (random() < 0.3) cuts.push(i);

        const expected = outcome((records) => records.push(...parse(text, options)));
        assert.deepEqual(parseInChunks(splitAt(text, cuts), options), expected, JSON.stringify({ text, cuts, options }));
      }
    });
  });

  it('stays linear in the input when a field and a record span many small chunks', { timeout: 10000 }, () => {
    const pieces = 200000;
    const parser = createParser();
    parser.write('"');
    for (let i = 0; i < pieces; i++) assert.deepEqual(parser.write(i % 2 ? 'x' : '""'), []);
    parser.write('",');
    for (let i = 0; i < pieces; i++) parser.write('y');
    const [record] = parser.write('\n');
    assert.equal(record[0], '"x'.repeat(pieces / 2));
    assert.equal(record[1], 'y'.repeat(pieces));
    assert.deepEqual(parser.end(), []);
  });
});

