'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { parse, stringify } = require('../src/csv.js');

describe('stringify', () => {
  it('joins fields with commas and records with CRLF, ending with one CRLF', () => {
    assert.equal(
      stringify([
        ['a', 'b'],
        ['c', 'd'],
      ]),
      'a,b\r\nc,d\r\n',
    );
  });

  it('returns an empty string for no rows', () => {
    assert.equal(stringify([]), '');
    assert.equal(stringify([], { header: ['a'] }), '');
  });

  it('writes numbers and booleans with String() and null or undefined as empty fields', () => {
    assert.equal(stringify([[1, -2.5, NaN, true, false, null, undefined, '']]), '1,-2.5,NaN,true,false,,,\r\n');
  });

  it('throws TypeError for values of any other type', () => {
    for (const value of [{}, [], new Date(0), Symbol('s'), 10n, () => 'x']) {
      assert.throws(() => stringify([['ok', value]]), TypeError, String(typeof value));
    }
  });

  it('throws TypeError when rows or a row is not an array', () => {
    for (const rows of [undefined, null, 'a,b', { 0: ['a'] }]) {
      assert.throws(() => stringify(rows), TypeError);
    }
    assert.throws(() => stringify([['a'], 'b']), TypeError);
    assert.throws(() => stringify([{ a: 1 }]), TypeError);
    assert.throws(() => stringify([null]), TypeError);
  });

  describe('quoting', () => {
    const cases = [
      ['a,b', '"a,b"'],
      ['say "hi"', '"say ""hi"""'],
      ['"', '""""'],
      ['a\nb', '"a\nb"'],
      ['a\rb', '"a\rb"'],
      [' lead', '" lead"'],
      ['trail ', '"trail "'],
      [' ', '" "'],
      ['in side', 'in side'],
      ['\ttab\t', '\ttab\t'],
      ['plain', 'plain'],
    ];
    for (const [value, expected] of cases) {
      it(`writes ${JSON.stringify(value)} as ${expected}`, () => {
        assert.equal(stringify([['x', value]]), `x,${expected}\r\n`);
      });
    }

    it('quotes on the configured delimiter, not on commas', () => {
      assert.equal(stringify([['a;b', 'c,d']], { delimiter: ';' }), '"a;b";c,d\r\n');
    });

    it('quotes a leading BOM at the start of the output so parse does not strip it', () => {
      assert.equal(stringify([['﻿a', '﻿b']]), '"﻿a",﻿b\r\n');
      assert.equal(stringify([['x'], ['﻿a']]), 'x\r\n﻿a\r\n');
    });
  });

  it('writes a record whose only field is empty as ""', () => {
    assert.equal(stringify([[''], [null], [undefined], ['', '']]), '""\r\n""\r\n""\r\n,\r\n');
  });

  describe('eol option', () => {
    it("accepts '\\n'", () => {
      assert.equal(stringify([['a'], ['b']], { eol: '\n' }), 'a\nb\n');
    });

    it('throws TypeError for anything else', () => {
      for (const eol of ['\r', '', '\n\r', ';', 1, null]) {
        assert.throws(() => stringify([['a']], { eol }), TypeError, JSON.stringify(eol));
      }
    });
  });

  describe('delimiter option', () => {
    it('separates fields with the given character', () => {
      assert.equal(stringify([['a', 'b']], { delimiter: '\t' }), 'a\tb\r\n');
    });

    it('throws TypeError for an invalid delimiter', () => {
      for (const delimiter of ['', '::', '"', '\r', '\n', 0, null]) {
        assert.throws(() => stringify([['a']], { delimiter }), TypeError, JSON.stringify(delimiter));
      }
    });
  });

  it('throws TypeError when options is not an object', () => {
    assert.throws(() => stringify([['a']], null), TypeError);
  });

  describe('header option', () => {
    it('writes the header, then object values in header order', () => {
      const rows = [
        { b: 2, a: 'x,y' },
        { a: null, b: true },
      ];
      assert.equal(stringify(rows, { header: ['a', 'b'] }), 'a,b\r\n"x,y",2\r\n,true\r\n');
    });

    it('writes a missing or inherited key as an empty field and ignores extra keys', () => {
      const inherited = Object.create({ a: 'inherited' });
      inherited.b = 'own';
      assert.equal(
        stringify([{ a: '1', extra: 'no' }, inherited], { header: ['a', 'b'] }),
        'a,b\r\n1,\r\n,own\r\n',
      );
    });

    it('accepts array rows alongside objects', () => {
      assert.equal(stringify([['1', '2'], { a: '3', b: '4' }], { header: ['a', 'b'] }), 'a,b\r\n1,2\r\n3,4\r\n');
    });

    it('quotes header names like other fields', () => {
      assert.equal(stringify([{ 'x,y': 1 }], { header: ['x,y'] }), '"x,y"\r\n1\r\n');
      assert.equal(stringify([{}], { header: [''] }), '""\r\n""\r\n');
    });

    it('throws TypeError for an invalid header or row', () => {
      assert.throws(() => stringify([{}], { header: 'a,b' }), TypeError);
      assert.throws(() => stringify([{}], { header: ['a', 1] }), TypeError);
      assert.throws(() => stringify([null], { header: ['a'] }), TypeError);
      assert.throws(() => stringify(['a'], { header: ['a'] }), TypeError);
      assert.throws(() => stringify([{ a: {} }], { header: ['a'] }), TypeError);
    });
  });
});

// Deterministic PRNG so failures are reproducible.
function mulberry32(seed) {
  let a = seed;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

describe('parse(stringify(rows)) round trip', () => {
  const pieces = ['', 'a', 'Z', ',', ';', '\t', '|', ' ', '"', '""', '\r', '\n', '\r\n', '﻿', 'é', '😀'];
  const optionSets = [];
  for (const delimiter of [undefined, ';', '\t', ' ', '|']) {
    for (const eol of [undefined, '\n']) {
      for (const skipEmptyLines of [false, true]) optionSets.push({ delimiter, eol, skipEmptyLines });
    }
  }

  function randomRows(random) {
    const rows = [];
    const rowCount = Math.floor(random() * 5);
    for (let r = 0; r < rowCount; r++) {
      const row = [];
      const fieldCount = 1 + Math.floor(random() * 4);
      for (let f = 0; f < fieldCount; f++) {
        let field = '';
        const length = Math.floor(random() * 4);
        for (let i = 0; i < length; i++) field += pieces[Math.floor(random() * pieces.length)];
        row.push(field);
      }
      rows.push(row);
    }
    return rows;
  }

  it('returns the same rows for edge-case rows under every option set', () => {
    const rows = [[''], ['', ''], [' '], ['﻿'], ['"'], ['\r\n', '\r', '\n'], ['a"b', ' c ']];
    for (const options of optionSets) {
      assert.deepEqual(parse(stringify(rows, options), options), rows, JSON.stringify(options));
    }
  });

  it('returns the same rows for random rows under every option set', () => {
    const random = mulberry32(7);
    for (let round = 0; round < 300; round++) {
      const rows = randomRows(random);
      for (const options of optionSets) {
        const text = stringify(rows, options);
        assert.deepEqual(parse(text, options), rows, JSON.stringify({ rows, options, text }));
      }
    }
  });

  it('returns the same objects through header mode', () => {
    const header = ['id', 'note', ' '];
    const rows = [
      { id: '1', note: 'a,"b"\r\nc', ' ': '' },
      { id: '', note: '', ' ': ' x ' },
    ];
    assert.deepEqual(parse(stringify(rows, { header }), { header: true }), rows);
  });
});

