// `rowIndex` is -1 for the header row. `leading` marks the first record of the output.
// An index loop rather than map(), so holes in a sparse row are written like undefined.
function formatRecord(values, delimiter, rowIndex, leading) {
  const fields = new Array(values.length);
  for (let i = 0; i < values.length; i++) {
    const field = formatValue(values[i], rowIndex, i);
    fields[i] = needsQuotes(field, delimiter) ? `"${field.replaceAll('"', '""')}"` : field;
  }
  if (fields.length === 1 && fields[0] === '') return '""';
  const line = fields.join(delimiter);
  // parse strips a BOM at the start of its input, so the output must not begin with one. That BOM
  // is the first field's first character or, when the first field is empty, a BOM delimiter.
  // Quoting the first field covers both; it holds no `"` to double, or it would be quoted already.
  if (leading && line.charCodeAt(0) === BOM) return `"${fields[0]}"${line.slice(fields[0].length)}`;
  return line;
}

